questionvariables.text:
/* 1. INITIALISATIONS PAR DÉFAUT (Sécurité STACK) */
num: x$ den: x$ ans_correct: 0$ txt_lim: "0"$ cas_txt: "1"$ deg_rule: ""$ explication: ""$ signe_txt: "positif (+)"$ err_sign_inf: 999$ err_0_inf: 999$ err_L_0: 999$ err_0_L: 999$ 
/* 2. GÉNÉRATION ALÉATOIRE */
r_type: rand(4)$ r_sub: rand(3)$ 
/* --- CAS 1 : Limite = 0 (Degré num < Degré den) --- */
if r_type = 1 and r_sub = 1 then num: 2*x^2 + 3*x - 1$ if r_type = 1 and r_sub = 2 then num: x^3 - 2*x + 1$ if r_type = 1 and r_sub = 3 then num: 5*x - 2$ if r_type = 1 then den: x^3 - 2*x^2 + x + 1$ if r_type = 1 then ans_correct: 0$ if r_type = 1 then txt_lim: "0"$ 
/* --- CAS 2 : Limite = L réel (Degrés égaux) --- */
if r_type = 2 and r_sub = 1 then num: 2*x^2 - x + 1$ if r_type = 2 and r_sub = 2 then num: 3*x^2 + 2*x$ if r_type = 2 and r_sub = 3 then num: -4*x^2 + 5$ if r_type = 2 and r_sub = 1 then den: x^2 + 3*x - 2$ if r_type = 2 and r_sub = 2 then den: -x^2 + 4$ if r_type = 2 and r_sub = 3 then den: 2*x^2 - x$ if r_type = 2 and r_sub = 1 then ans_correct: 2$ if r_type = 2 and r_sub = 2 then ans_correct: -3$ if r_type = 2 and r_sub = 3 then ans_correct: -2$ if r_type = 2 and r_sub = 1 then txt_lim: "2"$ if r_type = 2 and r_sub = 2 then txt_lim: "-3"$ if r_type = 2 and r_sub = 3 then txt_lim: "-2"$ 
/* --- CAS 3 : Limite = +inf (Degré num > Degré den, coeff positifs) --- */
if r_type = 3 and r_sub = 1 then num: x^3 - 2*x + 1$ if r_type = 3 and r_sub = 2 then num: 3*x^4 - x$ if r_type = 3 and r_sub = 3 then num: -2*x^3 + 5$ if r_type = 3 and r_sub = 1 then den: x^2 + 4$ if r_type = 3 and r_sub = 2 then den: 2*x^3 + x^2$ if r_type = 3 and r_sub = 3 then den: -x^2 - 1$ if r_type = 3 then ans_correct: inf$ if r_type = 3 then txt_lim: "+\infty"$ 
/* --- CAS 4 : Limite = -inf (Degré num > Degré den, coeff négatifs) --- */
if r_type = 4 and r_sub = 1 then num: -x^3 + 2*x^2$ if r_type = 4 and r_sub = 2 then num: 5*x^2 - 1$ if r_type = 4 and r_sub = 3 then num: 2*x^4 - 3$ if r_type = 4 and r_sub = 1 then den: x^2 - 5$ if r_type = 4 and r_sub = 2 then den: -2*x^3 + x$ if r_type = 4 and r_sub = 3 then den: -x^3 + 2*x$ if r_type = 4 then ans_correct: -inf$ if r_type = 4 then txt_lim: "-\infty"$ 
/* 3. CALCULS POUR LA CORRECTION */
func: num/den$ deg_num: hipow(num, x)$ deg_den: hipow(den, x)$ coeff_num: ev(leadcoef(num), simp)$ coeff_den: ev(leadcoef(den), simp)$ 
if coeff_num/coeff_den > 0 then signe_txt: "positif (+)"$ if coeff_num/coeff_den < 0 then signe_txt: "négatif (-)"$ 
if r_type = 1 then cas_txt: "1"$ if r_type = 1 then deg_rule: "Le degré du numérateur ({@deg_num@}) est STRICTEMENT INFÉRIEUR au degré du dénominateur ({@deg_den@})."$ if r_type = 1 then explication: "D'après le cours, dans ce cas, la limite en \(+\infty\) est égale à 0."$ 
if r_type = 2 then cas_txt: "2"$ if r_type = 2 then deg_rule: "Le degré du numérateur ({@deg_num@}) est ÉGAL au degré du dénominateur ({@deg_den@})."$ if r_type = 2 then explication: "D'après le cours, dans ce cas, la limite vaut le quotient des coefficients dominants : \(\frac{@coeff_num@}}{{@coeff_den@}} = {@ans_correct@}\)."$ 
if r_type = 3 then cas_txt: "3"$ if r_type = 4 then cas_txt: "3"$ if r_type = 3 or r_type = 4 then deg_rule: "Le degré du numérateur ({@deg_num@}) est STRICTEMENT SUPÉRIEUR au degré du dénominateur ({@deg_den@})."$ if r_type = 3 or r_type = 4 then explication: "D'après le cours, dans ce cas, la limite est infinie. On regarde le signe du quotient des coefficients dominants. En \(+\infty\), ce signe est {@signe_txt@}, donc la limite est {@txt_lim@}."$ 
/* 4. GÉNÉRATION DES ERREURS CLASSIQUES */
if ans_correct = inf then err_sign_inf: -inf$ if ans_correct = -inf then err_sign_inf: inf$ 
if ans_correct = inf or ans_correct = -inf then err_0_inf: 0$ 
if ans_correct = 0 then err_L_0: ev(coeff_num/coeff_den, simp)$ 
if ans_correct#0 and ans_correct#inf and ans_correct#-inf then err_0_L: 0$
